with base as (select *, initcap(trim(name)) as name_title from customers where segment = 'Corporate' or age is not null), customers_stats as (select country, is_active, max(credit_limit) - min(credit_limit) as credit_limit_range, avg(credit_limit) as avg_credit_limit from base group by country, is_active) select country, is_active, credit_limit_range, avg_credit_limit from customers_stats order by avg_credit_limit desc, country, is_active limit 1
